'use strict';
const DIGEST_UI6={render,bind,help};let digestShown6=null,digestActive6=null;
function closeDigest6(){if(digestActive6!==null){acknowledgeDigest6(digestActive6);persist();digestActive6=null;}el('modal').close();}
function digestDestination6(x){closeDigest6();if(x.target&&state.stores.some(s=>s.id===x.target)){if(x.view==='live')liveStore=x.target;if(x.view==='stores'){filterCity=loc(x.target).city;}if(x.view==='property')propertyCity5=loc(x.target).city;}goto(x.view);}
function showDigest6(week){const h=weeklyDigest6(week);if(!h)return;digestActive6=h.week;const current=h.week===state.week-1;show(`<span class="eyelabel">UZAVŘENÝ TÝDEN ${h.week}${current?'':' · ARCHIV'}</span><h2>Týdenní přehled firmy</h2><p class="sub">${current?'Co se právě stalo a co potřebuje tvoji pozornost.':'Tehdejší výsledky a zprávy zůstaly zachované. Správa otevře současný stav.'}</p><div class="report-overview5">${metric('VÝSLEDEK',money(h.profit),'Po plných nákladech a dani',h.profit>=0?'good':'bad')}${metric('HOTOVOST',money(h.cash),'Změna '+money(h.cashChange))}${metric('HOSTÉ',number(h.cups),'Skutečně prodané šálky')}${metric('REZERVA',number(h.reserve,1)+' týdnů','Pouze fixní náklady')}</div>${h.over?'<div class="warning"><strong>Firma nemá hotovost.</strong> Prověř výdaje a zásoby ve Financích. Ukládání umožní načíst starší firmu.</div>':''}${h.milestone?'<div class="tutorial">Splněn milník mezinárodního kávového impéria. Ve hře můžeš pokračovat.</div>':''}<div class="actions" style="margin:20px 0"><button class="primary" id="digestContinue6">Pokračovat v řízení</button><button class="soft" id="digestFinance6">Otevřít finance</button>${h.over?'<button class="soft" id="digestSaveHelp6">Ukládání & nová hra</button>':''}</div>${h.items.some(x=>x.severity===2)?`<section class="digest-section6"><h3>Neodkladné · ${h.items.filter(x=>x.severity===2).length}</h3><div class="actions">${h.items.filter(x=>x.severity===2).map(x=>`<button class="soft" data-digest-open6="${esc(x.key)}">${esc(x.title)}</button>`).join('')}</div></section>`:''}${h.items.length?Object.entries(DIGEST_CATEGORIES6).map(([cat,name])=>{const items=h.items.filter(x=>x.category===cat);if(!items.length)return '';return `<section class="digest-section6"><h3>${name} · ${items.length}</h3>${items.map(x=>`<article class="news digest-item6 ${x.severity===2?'digest-urgent6':''}"><span class="news-icon ${x.severity===2?'bad':''}">${x.severity===2?'!':'•'}</span><div style="flex:1;min-width:0"><strong>${esc(x.title)}</strong><small>${esc(x.text)}</small><p class="sub">${x.pending?(digestPending6(x)?'Čeká na rozhodnutí':'Vyřízeno nebo už není aktuální'):''}${x.due!==null?' · Termín T'+x.due:''}</p></div><button class="soft mini" data-digest-open6="${esc(x.key)}">${digestPending6(x)?'Řešit':'Otevřít'}</button></article>`).join('')}</section>`;}).join(''):empty('Tento týden bez nových nabídek, rozhodnutí nebo provozních výjimek.')}<details style="margin-top:24px"><summary>Archiv týdenních přehledů</summary><label for="digestHistory6">Uzavřený týden</label><select id="digestHistory6">${state.digest6.history.slice().reverse().map(x=>option(x.week,'Týden '+x.week+' · '+money(x.profit),h.week)).join('')}</select><p class="sub">Posledních 13 skutečných týdnů. Zprávy jsou historický snímek; platbu ani schválení neprovádí otevření přehledu.</p></details>`);el('digestContinue6').onclick=closeDigest6;el('digestFinance6').onclick=()=>{closeDigest6();goto('finance');};if(el('digestSaveHelp6'))el('digestSaveHelp6').onclick=()=>{closeDigest6();help();};el('digestHistory6').onchange=()=>showDigest6(Number(el('digestHistory6').value));for(const b of document.querySelectorAll('[data-digest-open6]'))b.onclick=()=>{const x=h.items.find(x=>x.key===b.dataset.digestOpen6);if(x)digestDestination6(x);};}
render=function(){DIGEST_UI6.render();let button=el('weeklyDigest6');if(!button){button=document.createElement('button');button.id='weeklyDigest6';button.className='soft mini';el('date').insertAdjacentElement('afterend',button);}const h=weeklyDigest6();button.textContent=h?'Přehled T'+h.week:'Týdenní přehled';button.disabled=!h;button.onclick=()=>showDigest6();if(digestShown6?.root!==state.digest6){digestShown6={root:state.digest6,week:state.digest6.seen};}if(h&&h.week>digestShown6.week&&h.week>state.digest6.seen){digestShown6.week=h.week;showDigest6(h.week);}};
bind=function(){DIGEST_UI6.bind();el('next').onclick=()=>{const h=act(nextWeek);if(h)toast('Týden uzavřen: '+money(h.profit));};};
const digestCloseOriginal6=el('close').onclick;el('close').onclick=()=>{if(digestActive6!==null)closeDigest6();else digestCloseOriginal6();};el('modal').addEventListener('close',()=>{if(digestActive6!==null){acknowledgeDigest6(digestActive6);persist();digestActive6=null;}});
help=function(){DIGEST_UI6.help();const p=document.createElement('p');p.textContent='Edice 05.16: Po každém odehraném týdnu se automaticky otevře přehled firmy. Obsahuje čekající rozhodnutí, nabídky odběratelů, nové a končící kontrakty, konkurenční přetahování lidí, osobní zprávy, provozní potíže a blížící se platby. Otevření správy nic samo neschválí. Tlačítko u herního data zpřístupní posledních 13 uzávěrek. Přečtení přehledu se uloží; nevyřízené položky připomene další týden.';el('modalContent').append(p);};el('help').onclick=help;render();
